//! The actual original body evaluation lends every policy hook to ONE sink.
//! RefCell is stack-only and every borrow ends before the next evaluator hook.
use super::*;
use crate::policy_body_demand::PolicyFailure as Failure;
use std::cell::RefCell;
struct Bridge<'s,'o,O>(&'s RefCell<&'o mut O>);
impl<'a,O:OriginalObserver<'a>> TypeIssueObserver<Failure> for Bridge<'_,'_,O>{fn undefined_type(&mut self,path:&str,at:Span)->Result<(),Failure>{TypeIssueObserver::undefined_type(&mut **self.0.borrow_mut(),path,at)}}
impl<'a,O:OriginalObserver<'a>> IterationObserver<Failure> for Bridge<'_,'_,O>{fn iterable(&mut self,ty:TypeFact,at:Span)->Result<(),Failure>{IterationObserver::iterable(&mut **self.0.borrow_mut(),ty,at)}fn invalid_range(&mut self,at:Span)->Result<(),Failure>{IterationObserver::invalid_range(&mut **self.0.borrow_mut(),at)}}
impl<'a,O:OriginalObserver<'a>> StaticObserver<Failure> for Bridge<'_,'_,O>{fn failure(&mut self,failure:crate::checker_static_reference::Failure<'_>,name:&str,procedure:bool,at:Span,expression:Span)->Result<(),Failure>{StaticObserver::failure(&mut **self.0.borrow_mut(),failure,name,procedure,at,expression)}}
impl<'a,O:OriginalObserver<'a>> CatchObserver<Failure> for Bridge<'_,'_,O>{fn parameters(&mut self,count:usize,at:Span,expression:Span)->Result<(),Failure>{CatchObserver::parameters(&mut **self.0.borrow_mut(),count,at,expression)}}
impl<'a,O:OriginalObserver<'a>> CaseObserver<Failure> for Bridge<'_,'_,O>{fn switch_started(&mut self,selector:&Expr,cases:&[dm_syntax::SwitchCase],default_present:bool,at:Span)->Result<(),Failure>{CaseObserver::switch_started(&mut **self.0.borrow_mut(),selector,cases,default_present,at)}fn logical_or(&mut self,cursor:dm_syntax::OriginalCaseCursor,expression:Span)->Result<(),Failure>{CaseObserver::logical_or(&mut **self.0.borrow_mut(),cursor,expression)}fn do_while_unreachable(&mut self,at:Span,condition:Span)->Result<(),Failure>{CaseObserver::do_while_unreachable(&mut **self.0.borrow_mut(),at,condition)}}
impl<'a,O:OriginalObserver<'a>> KeywordObserver<Failure> for Bridge<'_,'_,O>{fn begin_call(&mut self,tree:&SemanticTree,fact:&CallableFact,name:&str)->Result<(),Failure>{KeywordObserver::begin_call(&mut **self.0.borrow_mut(),tree,fact,name)}fn accepted_argument(&mut self,tree:&SemanticTree,fact:&CallableFact,receiver:SymbolId,name:&str,key:&Expr,at:Span)->Result<(),Failure>{KeywordObserver::accepted_argument(&mut **self.0.borrow_mut(),tree,fact,receiver,name,key,at)}}
impl<'a,O:OriginalObserver<'a>> ArgumentObserver<Failure> for Bridge<'_,'_,O>{fn reserve(&mut self,n:usize)->Result<(),Failure>{ArgumentObserver::reserve(&mut **self.0.borrow_mut(),n)}fn original_values(&self)->bool{ArgumentObserver::original_values(&**self.0.borrow())}fn begin_call(&mut self,tree:&SemanticTree,fact:&CallableFact,name:&str)->Result<(),Failure>{ArgumentObserver::begin_call(&mut **self.0.borrow_mut(),tree,fact,name)}fn argument(&mut self,tree:&SemanticTree,fact:&CallableFact,name:&str,key:Option<&Expr>,after:bool,at:Option<Span>,expression:Span)->Result<(),Failure>{ArgumentObserver::argument(&mut **self.0.borrow_mut(),tree,fact,name,key,after,at,expression)}fn finished(&mut self,tree:&SemanticTree,fact:&CallableFact,name:&str,args:&[Expr],named:&NamedArguments<'_>,values:OriginalArguments<'_>,at:Option<Span>,expression:Span)->Result<(),Failure>{ArgumentObserver::finished(&mut **self.0.borrow_mut(),tree,fact,name,args,named,values,at,expression)}}

impl<'a,O:OriginalObserver<'a>> OriginalEvents<'a,Failure> for Bridge<'_,'_,O>{fn expression_event(&mut self,event:Event<'a>)->Result<(),Failure>{self.0.borrow_mut().expression_event(event)}fn flow_event(&mut self,event:crate::checker_reachable::Event<'a>)->Result<(),Failure>{self.0.borrow_mut().flow_event(event)}fn access_row(&mut self,row:crate::checks_proc_visibility::Row<'a>)->Result<(),Failure>{self.0.borrow_mut().access_row(row)}fn immediate_row(&mut self,row:crate::checks::Diagnostic)->Result<(),Failure>{self.0.borrow_mut().immediate_row(row)}}
struct UnionDemand<'a,D>{inner:D,budget:&'a crate::checker_effects::output::ReportBudget}
impl<D:crate::checker_prefix_demand::Demand<Error=Failure>> crate::checker_prefix_demand::Demand for UnionDemand<'_,D>{type Error=Failure;fn source_checkpoint(&self)->Option<&dyn Fn()->std::io::Result<()>>{self.inner.source_checkpoint()}fn policy_failure(&self,failure:Failure)->Failure{self.inner.policy_failure(failure)}fn checkpoint(&self)->Result<(),Failure>{self.budget.charge(0).map_err(|_|self.inner.resource("combined body admission denied"))?;self.inner.checkpoint()}fn storage(&self,bytes:usize)->Result<(),Failure>{self.budget.charge(bytes).map_err(|_|self.inner.resource("combined body storage admission denied"))}fn owns_directive_binding(&self)->bool{self.inner.owns_directive_binding()}fn owns_return_expression_binding(&self)->bool{self.inner.owns_return_expression_binding()}fn profile(&self)->Option<dm_tree::checker_builtins::ValidatedCheckerProfile<'_>>{self.inner.profile()}fn resource(&self,message:&'static str)->Failure{self.inner.resource(message)}fn prefix_with_budget<T>(&self,archive:&BodyArchive,identity:dm_ir::ProcedureIdentity,budget:Option<&crate::checker_effects::output::ReportBudget>,consume:impl FnOnce(dm_tree::frontend::InitialSettingPrefix<'_>)->T)->Result<T,Failure>{self.inner.prefix_with_budget(archive,identity,budget.or(Some(self.budget)),consume)}}
pub(crate) fn archived_using<'a,O:OriginalObserver<'a>,D:crate::checker_prefix_demand::Demand<Error=Failure>>(

 archive:&'a BodyArchive,body:&'a ArchivedBody<'_>,resolver:&(impl Resolver+?Sized),profile:PackedU128,loan:crate::checker_effects::DraftLoan<'_>,prefix_demand:D,checkpoint:&dyn Fn()->std::io::Result<()>,observer:&mut O
)->Result<(),Failure>{
 checkpoint().map_err(Failure::Operational)?;if !body.belongs_to(archive)||!body.statement_body().original_literal_syntax_complete()||resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("combined original body/archive/resolver are foreign or incomplete".into())}archive.tree().validate_checker_builtin_profile(profile).map_err(|e|format!("combined original profile: {e:?}"))?;
 let levels=observer.access_levels();observer.body_started()?;
 let shared=RefCell::new(observer);let mut types=Bridge(&shared);let mut iteration=Bridge(&shared);let mut references=Bridge(&shared);let mut catches=Bridge(&shared);let mut cases=Bridge(&shared);let mut keywords=Bridge(&shared);let mut arguments=Bridge(&shared);let mut events=Bridge(&shared);
 let demand=UnionDemand{inner:prefix_demand,budget:loan.transient};
 let mut walker=Walker::new_using_with_type_issues(archive.tree(),Some(archive),&body.statement_body().parsed().local_variables,archive.expanded_source(),body.occurrence(),body.checker_parameters(profile)?,resolver,profile,Some(loan.transient),demand,Some(&mut types))?;
 walker.access=Some(crate::checks_proc_visibility::Access::for_all(archive,body,levels)?);walker.original_values=true;walker.finite_effect_events=false;walker.original_events=Some(&mut events);walker.effects=Some(loan);walker.iteration_errors=Some(&mut iteration);walker.static_errors=Some(&mut references);walker.catch_errors=Some(&mut catches);walker.case_errors=Some(&mut cases);walker.keywords=Some(&mut keywords);walker.argument_errors=Some(&mut arguments);
 crate::checker_reachable::archived_original_syntax_with_observer_using(body,&mut walker)?;walker.check_effect_admission()?;let rows=walker.access.take().expect("actual combined access").finish(resolver,profile,&walker.prefix_demand)?;for row in rows{walker.original_events.as_deref_mut().expect("combined events").access_row(row)?;}checkpoint().map_err(Failure::Operational)?;Ok(())
}
